package com.picviewer.app;
import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;
import org.robolectric.*;import org.robolectric.annotation.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import com.picviewer.core.*;
@RunWith(RobolectricTestRunner.class)
@org.robolectric.annotation.Config(sdk=34,qualifiers="w960dp-h600dp-land-mdpi")
@GraphicsMode(GraphicsMode.Mode.NATIVE)
@LooperMode(LooperMode.Mode.PAUSED)
public class AppTest {
 MainActivity a;
 @Before public void init(){a=Robolectric.buildActivity(MainActivity.class).setup().get();}
 @After public void done(){if(a!=null)a.onDestroy();}
 @Test public void welcomeRenders(){assertNotNull(a.root);capture("welcome");}
 @Test public void demoSelectionAndGallery(){a.startDemo();assertEquals(4,a.all.size());assertEquals(4,a.displayed.size());a.selection.set("여행",false);a.refreshSelection();assertEquals(2,a.displayed.size());a.selection.all("",true);a.refreshSelection();capture("gallery");}
 @Test public void emptySelectionIsSafe(){a.startDemo();a.selection.all("",false);a.refreshSelection();assertEquals(0,a.displayed.size());assertFalse(a.bottom.getChildAt(a.bottom.getChildCount()-1).isEnabled());}
 @Test public void pcOffStateRenders(){a.showStatus("PC에 연결할 수 없습니다","OFFLINE");capture("pc-off");}
 @Test public void authStateRenders(){a.showStatus("계정 또는 폴더를 확인해 주세요","AUTH");capture("auth");}
 @Test public void databaseRoundTrip(){IndexDb d=new IndexDb(a);java.util.List<Photo> p=java.util.Arrays.asList(new Photo("a/사진2.jpg",52,99));java.util.Set<String> f=new java.util.HashSet<>(java.util.Arrays.asList("","a"));d.replace(p,f);assertEquals(p,d.photos());assertEquals(f,d.folders());d.remove(p.get(0).path);assertTrue(d.photos().isEmpty());d.clear();d.close();}
 @Test public void sampleDimensionBounded(){assertEquals(4,Images.sample(8000,6000,1000,750));assertEquals(1,Images.sample(400,300,1000,750));}
 @Test public void platformImageDecode()throws Exception{a.startDemo();for(Photo p:a.all){Images.Decoded d=a.images.decode(p,960,600);assertNotNull(p.path,d.bitmap);assertTrue(d.bitmap.getWidth()<=1920);d.bitmap.recycle();}}
 @Test public void cacheKeepsOnlyLiveVersions()throws Exception{a.startDemo();a.images.file(a.all.get(0));assertEquals(1,a.images.cached(a.all).size());a.images.reconcile(java.util.Collections.emptyList());assertEquals(0,a.images.cached(a.all).size());}
 @Test public void demoDoesNotOverwriteServerSelection(){a.prefs.edit().putString("selection","{\"private-folder\":true}").commit();a.startDemo();a.selection.all("",false);a.saveSelection();assertEquals("{\"private-folder\":true}",a.prefs.getString("selection",""));}
 @Test public void playbackPauseAndReturn()throws Exception{a.startDemo();a.startPlayback(null);a.decode.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertTrue(a.playing);assertNotNull(a.shown);String current=a.playlist.current();a.togglePause();assertTrue(a.paused);a.advance(false);a.decode.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertNotEquals(current,a.playlist.current());capture("player");a.onBackPressed();assertFalse(a.playing);assertNull(a.shown);assertEquals(4,a.displayed.size());}
 @Test public void cachedOfflineRequiresExplicitChoice()throws Exception{a.startDemo();a.images.file(a.all.get(0));a.demo=false;a.images.demo=false;a.online=false;a.showStatus("PC에 연결할 수 없습니다","OFFLINE");assertFalse(a.offlineChoice==false&&a.playing);assertEquals(1,a.images.cached(a.all).size());}
 @Test public void recursiveToggleAndDirectChildren(){a.startDemo();a.selection.recursive=false;a.selection.all("",true);a.refreshSelection();assertEquals(0,a.displayed.size());a.selection.set("일상",true);a.refreshSelection();assertEquals(1,a.displayed.size());}
 @Test public void closedLoaderRefusesFurtherWork()throws Exception{a.startDemo();a.images.close();try{a.images.file(a.all.get(0));fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("CLOSED"));}}
 @Test public void clearCacheInvalidatesFiles()throws Exception{a.startDemo();a.images.file(a.all.get(0));long epoch=a.images.cacheEpoch;a.images.clear();assertTrue(a.images.cacheEpoch>epoch);assertEquals(0,a.images.bytes());}
 @Test public void authClassification(){assertEquals("AUTH",SmbSource.kind(new IOException("STATUS_LOGON_FAILURE")));assertEquals("DENIED",SmbSource.kind(new IOException("STATUS_ACCESS_DENIED")));assertEquals("MISSING",SmbSource.kind(new IOException("STATUS_OBJECT_NAME_NOT_FOUND")));assertEquals("SHARE",SmbSource.kind(new IOException("STATUS_BAD_NETWORK_NAME")));assertEquals("OFFLINE",SmbSource.kind(new IOException("Connection refused")));}
 @Test public void formatDetailsAreAvailable(){a.formats();assertNotNull(org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog());org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().dismiss();}
 @Test public void licenseDetailsAreAvailable(){a.licenses();assertNotNull(org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog());org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().dismiss();}
 @Test public void largeFolderListIsVirtualized(){a.startDemo();for(int i=0;i<2000;i++)a.folders.add("many/folder"+i);a.renderFolders();ListView list=(ListView)a.sidebar.getChildAt(1);assertEquals(a.folders.size(),list.getAdapter().getCount());capture("gallery-large");assertTrue(list.getChildCount()<40);}
 @Test public void portraitLayoutKeepsPlaybackControls(){a.startDemo();android.content.res.Configuration c=new android.content.res.Configuration(a.getResources().getConfiguration());c.orientation=android.content.res.Configuration.ORIENTATION_PORTRAIT;a.getResources().updateConfiguration(c,a.getResources().getDisplayMetrics());a.gallery();assertNotNull(a.bottom);assertEquals(4,a.displayed.size());}
 @Test public void cacheChoiceIsExplicitAndCanRecover(){a.startDemo();a.offlineChoice=false;a.demo=false;a.images.online=false;a.online=false;a.showStatus("PC에 연결할 수 없습니다","OFFLINE");assertFalse(a.playing);assertFalse(a.offlineChoice);assertTrue(a.getWindow().getDecorView().getVisibility()==View.VISIBLE);}
 @Test public void pageStopsAndFreesDisplayedBitmap()throws Exception{a.startDemo();a.startPlayback(null);a.decode.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();Bitmap before=a.shown;assertNotNull(before);a.welcome();assertFalse(a.playing);assertNull(a.shown);assertTrue(before.isRecycled());}
 @Test public void rapidSwipeDiscardsOldLoads()throws Exception{a.startDemo();a.startPlayback(null);for(int i=0;i<50;i++)a.advance(false);a.decode.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertNotNull(a.shown);assertEquals(a.playlist.current(),a.picture.getTag());assertEquals(View.GONE,a.loading.getVisibility());}
 void connectFixture(boolean wrongPassword)throws Exception{Assume.assumeNotNull(System.getenv("PICVIEWER_TEST_PORT"));a.stopWork();Config c=new Config();c.host="127.0.0.1";c.port=Integer.parseInt(System.getenv("PICVIEWER_TEST_PORT"));c.user=System.getenv("PICVIEWER_TEST_USER");c.password=wrongPassword?"wrong-fixture-password":System.getenv("PICVIEWER_TEST_PASSWORD");c.share="photos";a.config=c;a.images.close();a.images=new Images(a,c);a.all=new java.util.ArrayList<>();a.folders=new java.util.HashSet<>();a.scan(true);a.network.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}
 @Test public void smbConnectToGalleryAndPlayback()throws Exception{connectFixture(false);assertTrue(a.online);assertFalse(a.scanning);assertEquals(4,a.all.size());assertEquals(4,a.displayed.size());a.startPlayback("여행/사진1.jpg");a.decode.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertNotNull(a.shown);assertEquals(View.GONE,a.loading.getVisibility());assertEquals("여행/사진1.jpg",a.playlist.current());}
 @Test public void smbWrongPasswordShowsAuthAndStopsPolling()throws Exception{connectFixture(true);assertFalse(a.online);assertEquals("AUTH",a.failure);assertFalse(a.playing);assertNull(a.grid);assertFalse(a.scanning);}
 @Test public void smbRescanUpdatesUiAfterAddDelete()throws Exception{connectFixture(false);java.nio.file.Path file=java.nio.file.Paths.get(System.getenv("PICVIEWER_TEST_ROOT")).resolve("added-ui.jpg");java.nio.file.Files.write(file,new byte[]{1,2,3});try{a.scan(false);a.network.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(5,a.displayed.size());}finally{java.nio.file.Files.deleteIfExists(file);}a.scan(false);a.network.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(4,a.displayed.size());}
 @Test public void simulatedPlaybackSoak100Steps()throws Exception{a.startDemo();a.startPlayback(null);a.togglePause();for(int i=0;i<100;i++){a.advance(false);a.decode.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertNotNull("frame "+i,a.shown);assertFalse(a.shown.isRecycled());assertEquals(a.playlist.current(),a.picture.getTag());}a.gallery();assertNull(a.shown);assertFalse(a.playing);}
 void capture(String name){try{View v=a.getWindow().getDecorView();v.measure(View.MeasureSpec.makeMeasureSpec(960,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(600,View.MeasureSpec.EXACTLY));v.layout(0,0,960,600);a.thumbs.submit(()->{}).get(15,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();v.measure(View.MeasureSpec.makeMeasureSpec(960,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(600,View.MeasureSpec.EXACTLY));v.layout(0,0,960,600);Bitmap b=Bitmap.createBitmap(960,600,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));File out=new File(System.getProperty("picviewer.screenshots","build/screenshots"));out.mkdirs();try(OutputStream s=new FileOutputStream(new File(out,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,s);}b.recycle();}catch(Exception e){throw new AssertionError(e);}}
}
